  async function card(
    roomId: string,
    cardType: string,
    body: Record<string, unknown>,
    ageMinutes = 10,
    authorId = AGENT,
  ): Promise<string> {
    sequence += 1;
    const id = `card-${sequence}`.padEnd(64, '0');
    await database.query(
      `INSERT INTO messages(id,room_id,author_id,text,presentation,card_type,card,created_at)
       VALUES($1,$2,$3,'card','card',$4,$5::jsonb,now() - $6 * interval '1 minute')`,
      [id, roomId, authorId, cardType, JSON.stringify(body), ageMinutes],
    );
    return id;
  }
  const hoots = { pubkey: AGENT, kind: 'agent', name: 'Hoots' };
  const approvals = async (viewer = VIEWER) => {
    const items = (await phone.execute('readNeedsYou', { workspaceId: WORKSPACE }, viewer)).items;
    expect((await phone.execute('countNeedsYou', { workspaceId: WORKSPACE }, viewer)).count).toBe(items.length);
    return items.filter((item) => item.approval).map((item) => item.approval);
  };

