  expect((await db.query(`SELECT last_wake_at FROM sentry_wake_state`)).rows).toEqual([{last_wake_at:null}]);
  await db.query(`UPDATE memberships SET removed_at=NULL WHERE identity_id=$1 AND room_id=$2`,[JELLYBEAN,ROOM]);
